situation_event = {
	id = toxoids.8005
	title = toxoids.8005.name
	desc = toxoids.8005.desc
	picture = GFX_evt_knights
	show_sound = evn_tox_knights_of_the_toxic_god

	is_triggered_only = yes

	trigger = {
		current_situation_approach = situation_toxic_knights_frugal
